  function esc(v) { return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) { return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]; }); }
  function injectStyle() { if (document.getElementById('saudiBuyerStyle')) return; var s=document.createElement('style'); s.id='saudiBuyerStyle'; s.textContent='.saudi-wrap{background:#fff;border:1px solid #e7e3dc;border-radius:22px;padding:24px}.saudi-head{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:20px}.saudi-head h2{font-size:28px;margin:6px 0}.saudi-head p{color:#6d746f}.saudi-profile{background:#edf2ef;padding:14px 18px;border-radius:14px;font-size:12px;line-height:1.7}.saudi-toolbar{display:flex;gap:10px;margin-bottom:16px}.saudi-toolbar input{flex:1;border:1px solid #e7e3dc;border-radius:12px;padding:12px}.saudi-toolbar button,.saudi-actions button,.saudi-actions a{border:0;border-radius:10px;padding:9px 12px;background:#183d31;color:#fff;text-decoration:none;font-size:12px;font-weight:800;cursor:pointer}.saudi-card{border:1px solid #e7e3dc;border-radius:16px;padding:17px;margin:10px 0;background:#fff}.saudi-main{display:flex;justify-content:space-between;gap:15px}.saudi-main h3{margin:0 0 5px;font-size:17px}.saudi-meta{font-size:12px;color:#6d746f}.saudi-main p{font-size:12px;color:#58615c}.saudi-score{min-width:64px;height:64px;border-radius:50%;background:#dfece6;color:#183d31;display:grid;place-items:center;font-size:20px;font-weight:900}.saudi-score small{font-size:9px;margin-left:2px}.saudi-info{display:flex;gap:20px;border-top:1px solid #eee;padding-top:10px;font-size:12px;color:#58615c}.saudi-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.saudi-actions a{background:#245646}.saudi-actions .saudi-watch{background:#af7b3c}.saudi-msg{font-size:12px;margin-top:9px;color:#245646}.saudi-foot{margin-top:16px;padding:12px;background:#f5eee4;border-radius:12px;font-size:11px;color:#675542}@media(max-width:700px){.saudi-head{flex-direction:column}.saudi-toolbar{flex-direction:column}.saudi-info{flex-direction:column;gap:5px}}'; document.head.appendChild(s); }
  function mailHref(c) { if (!c.email) return ''; var subject=encodeURIComponent('Türkiye’den Çanta ve Hediyelik Ürün Tedarik Teklifi – PuduBag'); var body=encodeURIComponent('Merhaba,\n\nBen PuduBag Atölye’den yazıyorum. Türkiye’de çanta ve hediyelik ürünler üretiyoruz. Suudi Arabistan pazarında iş ortaklığı ve toptan tedarik konusunda görüşmek isteriz.\n\nWeb: '+profile.web+'\nInstagram: '+profile.instagram+'\nTelefon / WhatsApp: '+profile.phone+'\nE-posta: '+profile.email+'\n\nUygun olursanız ürün kataloğumuzu ve fiyatlarımızı paylaşabiliriz.\n\nSaygılarımla,\nPuduBag Atölye'); return 'mailto:'+encodeURIComponent(c.email)+'?subject='+subject+'&body='+body; }
  function render() { injectStyle(); var view=document.getElementById('view-saudi'); if(!view)return; var rows=candidates.map(function(c,i){var links='';if(c.web)links+='<a href="'+esc(c.web)+'" target="_blank" rel="noopener">Web</a> ';if(c.instagram)links+='<a href="'+esc(c.instagram)+'" target="_blank" rel="noopener">Instagram</a> ';var mail=c.email?'<a href="'+mailHref(c)+'">✉ Mail Hazırla</a>':'<button class="saudi-hunter" data-i="'+i+'">Hunter ile E-posta Bul</button>';return '<div class="saudi-card"><div class="saudi-main"><div><h3>'+esc(c.name)+'</h3><div class="saudi-meta">📍 '+esc(c.city)+' · 🏷️ '+esc(c.category)+'</div><p>'+esc(c.note)+'</p></div><div class="saudi-score">'+c.score+'<small>/100</small></div></div><div class="saudi-info"><span>✉ '+esc(c.email||'E-posta aranacak')+'</span><span>☎ '+esc(c.phone||'—')+'</span></div><div class="saudi-actions">'+links+mail+'<button class="saudi-watch" data-i="'+i+'">⭐ Takibe Al</button></div><div class="saudi-msg" id="saudi-msg-'+i+'"></div></div>';}).join(''); view.innerHTML='<div class="saudi-wrap"><div class="saudi-head"><div><div class="eyebrow">30 AĞUSTOS SUUDİ ARABİSTAN SEFERİ</div><h2>🇸🇦 Suudi Arabistan Alıcıları</h2><p>Çanta, hediyelik, souvenir, Hac/Umre ve kurumsal hediye alıcıları.</p></div><div class="saudi-profile"><b>PuduBag</b><br>'+esc(profile.phone)+'<br>'+esc(profile.email)+'</div></div><div class="saudi-toolbar"><input id="saudiFilter" placeholder="Şehir, firma veya kategori filtrele…"><button id="saudiMailAll">✉ Seçilenlere Mail Hazırla</button></div><div id="saudiList">'+rows+'</div><div class="saudi-foot">E-posta bulunmayan firmalar Hunter ile zenginleştirilecek. Gönderimden önce alıcıları sen onaylayacaksın.</div></div>'; bind(); }
  function bind(){var filter=document.getElementById('saudiFilter');if(filter)filter.addEventListener('input',function(){var q=filter.value.toLowerCase();document.querySelectorAll('.saudi-card').forEach(function(el){el.style.display=el.textContent.toLowerCase().indexOf(q)>=0?'':'none';});});document.querySelectorAll('.saudi-watch').forEach(function(btn){btn.addEventListener('click',function(){var c=candidates[Number(btn.dataset.i)],msg=document.getElementById('saudi-msg-'+btn.dataset.i);msg.textContent='⭐ '+c.name+' takip için işaretlendi. Canlı CRM kimliği eşleştirmesi tamamlandıktan sonra kalıcı takip kaydı açılacak.';btn.textContent='✓ Takipte';});});document.querySelectorAll('.saudi-hunter').forEach(function(btn){btn.addEventListener('click',function(){var c=candidates[Number(btn.dataset.i)],msg=document.getElementById('saudi-msg-'+btn.dataset.i);msg.textContent='Hunter e-posta zenginleştirmesi: '+c.name+' için mevcut canlı Hunter akışına bağlanacak.';});});var all=document.getElementById('saudiMailAll');if(all)all.addEventListener('click',function(){var emails=candidates.filter(function(c){return c.email;}).map(function(c){return c.email;});if(emails.length)window.location.href=mailHref({email:emails.join(',')});});}
